class WebSmokeTest {
    private static Tomcat tomcat; private static Path base; private static int port; private static long patientId,doctorId,deliveryId,appointmentId,pendingAppointmentId,reviewPrescriptionId,medicineId;
    private static final String PATIENT="web.patient@local.test",DOCTOR="web.doctor@local.test",LEGACY_DOCTOR="meera@onlinemedic.local",ADMIN="web.admin@local.test",PHARMACY="web.pharmacy@local.test",DELIVERY="web.delivery@local.test";
    private static final String PASSWORD="WebSmoke12345!";

    @BeforeAll static void startWebApplication() throws Exception {
        System.setProperty("DATABASE_URL","jdbc:h2:mem:online_medic_test;MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1");System.setProperty("DATABASE_USER","sa");System.setProperty("DATABASE_PASSWORD","");
        prepareDatabase();
        base=Files.createTempDirectory("online-medic-tomcat-");tomcat=new Tomcat();tomcat.setBaseDir(base.toString());tomcat.setPort(0);tomcat.getConnector().setProperty("address","127.0.0.1");
        Path web=Path.of("src/main/webapp").toAbsolutePath();Context context=tomcat.addWebapp("",web.toString());context.setParentClassLoader(Thread.currentThread().getContextClassLoader());
        StandardRoot resources=new StandardRoot(context);context.setResources(resources);resources.createWebResourceSet(org.apache.catalina.WebResourceRoot.ResourceSetType.PRE,"/WEB-INF/classes",Path.of("target/classes").toAbsolutePath().toUri().toURL(),"/");
        context.addServletContainerInitializer(new JasperInitializer(),null);tomcat.start();port=tomcat.getConnector().getLocalPort();
    }
    @AfterAll static void stopWebApplication() throws Exception {
        if(tomcat!=null){try{tomcat.stop();}finally{tomcat.destroy();}}
        if(base!=null&&Files.exists(base))try(var paths=Files.walk(base)){paths.sorted(Comparator.reverseOrder()).forEach(path->{try{Files.deleteIfExists(path);}catch(java.io.IOException e){throw new java.io.UncheckedIOException(e);}});}
    }

    @Test void publicAndRolePagesRenderWithAuthorization() throws Exception {
        for(String path:new String[]{"/","/login","/register","/doctors","/doctors?id="+doctorId,"/medicines","/medicines?id="+medicineId})assertPage(path,null,200);assertNavigationLinks("/",null,true);
        assertPage("/payment?appointment="+pendingAppointmentId,null,302);
        String patientCookie=login(PATIENT);for(String path:new String[]{"/dashboard","/appointments","/orders","/prescriptions","/notifications","/cart","/patient/profile","/consultation?id="+appointmentId,"/chat?appointment="+appointmentId,"/payment?appointment="+pendingAppointmentId})assertPage(path,patientCookie,200);assertNavigationLinks("/dashboard",patientCookie,true);exercisePatientProfile(patientCookie);
        completeAppointmentPayment(patientCookie);
        assertPage("/admin",patientCookie,403);
        String doctorCookie=login(DOCTOR);assertPage("/dashboard",doctorCookie,200);assertNavigationLinks("/dashboard",doctorCookie,false);String legacyDoctorCookie=loginAs(LEGACY_DOCTOR,"DoctorDemo123!","doctor");assertPage("/dashboard",legacyDoctorCookie,200);String previewDoctorCookie=loginAs("showcase.aarav@onlinemedic.local","DoctorDemo123!","doctor");assertPage("/dashboard",previewDoctorCookie,200);assertPage("/doctor/appointments",doctorCookie,200);assertPage("/doctor/availability",doctorCookie,200);exerciseDoctorAvailability(doctorCookie);
        String pharmacyCookie=login(PHARMACY);assertPage("/dashboard",pharmacyCookie,200);assertPage("/pharmacist/manage",pharmacyCookie,200);assertPage("/pharmacist/orders",pharmacyCookie,200);assertPage("/pharmacist/returns",pharmacyCookie,200);assertPage("/prescriptions",pharmacyCookie,200);reviewPrescriptionIsOneTime(pharmacyCookie);exerciseVideoCall(patientCookie,doctorCookie,pharmacyCookie);assertPage("/pharmacist/returns",doctorCookie,403);
        String deliveryCookie=login(DELIVERY);assertPage("/dashboard",deliveryCookie,200);assertNavigationLinks("/dashboard",deliveryCookie,false);assertPage("/delivery",deliveryCookie,200);
        String adminCookie=login(ADMIN);for(String path:new String[]{"/dashboard","/admin","/admin/orders","/admin/doctors","/admin/staff","/prescriptions"})assertPage(path,adminCookie,200);assertNavigationLinks("/admin",adminCookie,false);exerciseAdminStaff(adminCookie);assertPage("/admin",patientCookie,403);
    }

    private static void assertPage(String path,String cookie,int expected)throws Exception{HttpURLConnection c=open(path,cookie);assertEquals(expected,c.getResponseCode(),path+" response");if(expected==200){String body=new String(c.getInputStream().readAllBytes(),StandardCharsets.UTF_8);assertTrue(body.contains("online")||body.contains("Online Medic")||body.contains("Appointment")||body.equals("[]"),path+" should render page content");}c.disconnect();}
    private static void assertNavigationLinks(String path,String cookie,boolean visible)throws Exception{HttpURLConnection c=open(path,cookie);assertEquals(200,c.getResponseCode(),path+" navigation response");String body=new String(c.getInputStream().readAllBytes(),StandardCharsets.UTF_8);c.disconnect();for(String label:new String[]{"Find a doctor","Pharmacy","Cart"})assertEquals(visible,body.contains(">"+label+"</a>"),label+" navigation visibility on "+path);}
    private static void completeAppointmentPayment(String cookie)throws Exception{
        HttpURLConnection page=open("/payment?appointment="+pendingAppointmentId,cookie);assertEquals(200,page.getResponseCode());String body=new String(page.getInputStream().readAllBytes(),StandardCharsets.UTF_8);Matcher matcher=Pattern.compile("name=\\\"csrfToken\\\" value=\\\"([^\\\"]+)\\\"").matcher(body);assertTrue(matcher.find(),"payment form should render its CSRF token");page.disconnect();
        String data="csrfToken="+enc(matcher.group(1))+"&appointmentId="+pendingAppointmentId+"&method=DEMO_CARD&outcome=success";HttpURLConnection post=open("/payment",cookie);post.setRequestMethod("POST");post.setDoOutput(true);post.setRequestProperty("Content-Type","application/x-www-form-urlencoded;charset=UTF-8");post.getOutputStream().write(data.getBytes(StandardCharsets.UTF_8));assertEquals(302,post.getResponseCode(),"successful demo payment should redirect back to appointments");post.disconnect();
        try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT status,payment_status FROM appointments WHERE id=?")){p.setLong(1,pendingAppointmentId);try(ResultSet r=p.executeQuery()){assertTrue(r.next());assertEquals("CONFIRMED",r.getString(1));assertEquals("SUCCESS",r.getString(2));}}
    }
    private static void reviewPrescriptionIsOneTime(String cookie)throws Exception{
        HttpURLConnection page=open("/prescriptions",cookie);assertEquals(200,page.getResponseCode());String body=new String(page.getInputStream().readAllBytes(),StandardCharsets.UTF_8);Matcher matcher=Pattern.compile("name=\"csrfToken\" value=\"([^\"]+)\"").matcher(body);assertTrue(matcher.find());page.disconnect();
        postPrescriptionReview(cookie,matcher.group(1),"VERIFIED");assertEquals("VERIFIED",prescriptionStatus());postPrescriptionReview(cookie,matcher.group(1),"REJECTED");assertEquals("VERIFIED",prescriptionStatus());
    }
    private static void postPrescriptionReview(String cookie,String csrf,String status)throws Exception{String data="csrfToken="+enc(csrf)+"&prescriptionId="+reviewPrescriptionId+"&status="+status+"&reason="+enc("Reviewed in web smoke test");HttpURLConnection post=open("/prescriptions",cookie);post.setRequestMethod("POST");post.setDoOutput(true);post.setRequestProperty("Content-Type","application/x-www-form-urlencoded;charset=UTF-8");post.getOutputStream().write(data.getBytes(StandardCharsets.UTF_8));assertEquals(302,post.getResponseCode());post.disconnect();}
    private static String prescriptionStatus()throws Exception{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT status FROM prescriptions WHERE id=?")){p.setLong(1,reviewPrescriptionId);try(ResultSet r=p.executeQuery()){assertTrue(r.next());return r.getString(1);}}}
    private static void exercisePatientProfile(String cookie)throws Exception{
        String token=csrfFrom("/patient/profile",cookie);
        postForm("/patient/profile",cookie,"csrfToken="+enc(token)+"&action=saveProfile&name="+enc("Smoke Test Patient")+"&phone="+enc("+91 90000 22222")+"&dateOfBirth=1990-01-01&gender=Prefer+not+to+say&emergencyContact="+enc("Contact · 9000011111"));
        try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT u.full_name,u.phone,p.gender FROM users u JOIN patient_profiles p ON p.user_id=u.id WHERE u.id=?")){p.setLong(1,patientId);try(ResultSet r=p.executeQuery()){assertTrue(r.next());assertEquals("Smoke Test Patient",r.getString(1));assertEquals("+91 90000 22222",r.getString(2));assertEquals("Prefer not to say",r.getString(3));}}
        postForm("/patient/profile",cookie,"csrfToken="+enc(token)+"&action=saveAddress&label=Smoke+QA&line1="+enc("221 Test Road")+"&city=Asansol&district=Paschim+Bardhaman&state=West+Bengal&postalCode=713305&isDefault=true");
        long addressId;try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT id FROM addresses WHERE user_id=? AND label='Smoke QA' ORDER BY id DESC LIMIT 1")){p.setLong(1,patientId);try(ResultSet r=p.executeQuery()){assertTrue(r.next());addressId=r.getLong(1);}}
        postForm("/patient/profile",cookie,"csrfToken="+enc(token)+"&action=saveAddress&addressId="+addressId+"&label=Smoke+QA+Updated&line1="+enc("221 Updated Test Road")+"&city=Asansol&district=Paschim+Bardhaman&state=West+Bengal&postalCode=713305&isDefault=true");
        try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT line1,is_default FROM addresses WHERE id=? AND user_id=?")){p.setLong(1,addressId);p.setLong(2,patientId);try(ResultSet r=p.executeQuery()){assertTrue(r.next());assertEquals("221 Updated Test Road",r.getString(1));assertTrue(r.getBoolean(2));}}
        postForm("/patient/profile",cookie,"csrfToken="+enc(token)+"&action=makeDefault&addressId="+addressId);
        postForm("/patient/profile",cookie,"csrfToken="+enc(token)+"&action=deleteAddress&addressId="+addressId);
        try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM addresses WHERE id=? AND user_id=?")){p.setLong(1,addressId);p.setLong(2,patientId);try(ResultSet r=p.executeQuery()){assertTrue(r.next());assertEquals(0,r.getInt(1));}}
    }
    private static void exerciseAdminStaff(String cookie)throws Exception{
        HttpURLConnection page=open("/admin/staff",cookie);assertEquals(200,page.getResponseCode());String body=new String(page.getInputStream().readAllBytes(),StandardCharsets.UTF_8);assertTrue(body.contains(DELIVERY),"admin staff page should list delivery accounts");Matcher matcher=Pattern.compile("name=\"csrfToken\" value=\"([^\"]+)\"").matcher(body);assertTrue(matcher.find());page.disconnect();
        postForm("/admin/staff",cookie,"csrfToken="+enc(matcher.group(1))+"&action=updateStaff&staffId="+deliveryId+"&role=DELIVERY&name="+enc("Updated QA Courier")+"&email="+enc(DELIVERY)+"&phone="+enc("+91 90000 11111")+"&credential="+enc("Bike-42")+"&active=true&newPassword=");
        try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT u.full_name,u.phone,d.vehicle_number,d.active FROM users u LEFT JOIN delivery_staff_profiles d ON d.user_id=u.id WHERE u.id=? AND u.role='DELIVERY'")){p.setLong(1,deliveryId);try(ResultSet r=p.executeQuery()){assertTrue(r.next());assertEquals("Updated QA Courier",r.getString(1));assertEquals("+91 90000 11111",r.getString(2));assertEquals("Bike-42",r.getString(3));assertTrue(r.getBoolean(4));}}
    }
    private static void exerciseVideoCall(String patientCookie,String doctorCookie,String pharmacistCookie)throws Exception{
        String pagePath="/consultation?id="+appointmentId;HttpURLConnection page=open(pagePath,patientCookie);assertEquals(200,page.getResponseCode());String pageBody=new String(page.getInputStream().readAllBytes(),StandardCharsets.UTF_8);assertTrue(pageBody.contains("One-to-one video consultation"));Matcher tokenMatch=Pattern.compile("name=\"csrfToken\" value=\"([^\"]+)\"").matcher(pageBody);assertTrue(tokenMatch.find());String patientCsrf=tokenMatch.group(1);page.disconnect();String doctorCsrf=csrfFrom(pagePath,doctorCookie);
        String started=postVideo(patientCookie,patientCsrf,"start",appointmentId,0,"","" );Matcher callMatch=Pattern.compile("\\\"id\\\":(\\d+),\\\"startedBy\\\":(\\d+),\\\"status\\\":\\\"RINGING\\\"").matcher(started);assertTrue(callMatch.find(),"A patient should be able to start a call: "+started);long callId=Long.parseLong(callMatch.group(1));
        assertEquals(403,open("/video-signal?appointmentId="+appointmentId+"&after=0",pharmacistCookie).getResponseCode());
        String offer="{\"type\":\"offer\",\"sdp\":\"test-offer\"}";assertTrue(postVideo(patientCookie,patientCsrf,"signal",appointmentId,callId,"OFFER",offer).contains("\"sent\":true"));
        HttpURLConnection incoming=open("/video-signal?appointmentId="+appointmentId+"&after=0",doctorCookie);assertEquals(200,incoming.getResponseCode());String incomingJson=new String(incoming.getInputStream().readAllBytes(),StandardCharsets.UTF_8);incoming.disconnect();assertTrue(incomingJson.contains("\"type\":\"OFFER\""));
        String answer="{\"type\":\"answer\",\"sdp\":\"test-answer\"}";assertTrue(postVideo(doctorCookie,doctorCsrf,"accept",appointmentId,callId,"","").contains("\"status\":\"ACTIVE\""));assertTrue(postVideo(doctorCookie,doctorCsrf,"signal",appointmentId,callId,"ANSWER",answer).contains("\"sent\":true"));
        HttpURLConnection returned=open("/video-signal?appointmentId="+appointmentId+"&after=0",patientCookie);String returnedJson=new String(returned.getInputStream().readAllBytes(),StandardCharsets.UTF_8);returned.disconnect();assertTrue(returnedJson.contains("\"type\":\"ANSWER\""));
        assertTrue(postVideo(doctorCookie,doctorCsrf,"end",appointmentId,callId,"","").contains("\"ended\":true"));HttpURLConnection ended=open("/video-signal?appointmentId="+appointmentId+"&after=0",patientCookie);String endedJson=new String(ended.getInputStream().readAllBytes(),StandardCharsets.UTF_8);ended.disconnect();assertTrue(endedJson.contains("\"status\":\"ENDED\""));assertTrue(endedJson.contains("\"signals\":[]"));
        postForm("/doctor/appointments",doctorCookie,"csrfToken="+enc(doctorCsrf)+"&appointmentId="+appointmentId+"&status=COMPLETED");HttpURLConnection blockedRoom=open(pagePath,patientCookie);blockedRoom.setInstanceFollowRedirects(false);assertEquals(302,blockedRoom.getResponseCode());assertTrue(blockedRoom.getHeaderField("Location").endsWith("/appointments"));blockedRoom.disconnect();HttpURLConnection deniedChat=open("/chat?appointment="+appointmentId,patientCookie);assertEquals(403,deniedChat.getResponseCode());deniedChat.disconnect();HttpURLConnection patientAppointments=open("/appointments",patientCookie);String listBody=new String(patientAppointments.getInputStream().readAllBytes(),StandardCharsets.UTF_8);patientAppointments.disconnect();assertFalse(listBody.contains("href=\"/consultation?id="+appointmentId+"\""));assertTrue(listBody.contains("Book a new appointment"));HttpURLConnection doctorRoom=open(pagePath,doctorCookie);assertEquals(200,doctorRoom.getResponseCode());String doctorBody=new String(doctorRoom.getInputStream().readAllBytes(),StandardCharsets.UTF_8);doctorRoom.disconnect();assertTrue(doctorBody.contains("This appointment is closed"));assertFalse(doctorBody.contains("data-video-call"));
    }
    private static String postVideo(String cookie,String csrf,String action,long appointment,long callId,String type,String payload)throws Exception{String data="csrfToken="+enc(csrf)+"&action="+enc(action)+"&appointmentId="+appointment+(callId>0?"&callId="+callId:"")+(type.isEmpty()?"":"&type="+enc(type))+(payload.isEmpty()?"":"&payload="+enc(payload));HttpURLConnection post=open("/video-signal",cookie);post.setRequestMethod("POST");post.setDoOutput(true);post.setRequestProperty("Content-Type","application/x-www-form-urlencoded;charset=UTF-8");post.getOutputStream().write(data.getBytes(StandardCharsets.UTF_8));int status=post.getResponseCode();String body=new String((status>=400?post.getErrorStream():post.getInputStream()).readAllBytes(),StandardCharsets.UTF_8);assertEquals(200,status,"video signaling request should succeed: "+body);post.disconnect();return body;}
    private static void exerciseDoctorAvailability(String cookie)throws Exception{
        String token=csrfFrom("/doctor/availability",cookie);LocalDate firstDate=LocalDate.now().plusDays(24);
        postForm("/doctor/availability",cookie,"csrfToken="+enc(token)+"&action=add&date="+firstDate+"&start=13%3A30&end=14%3A00");
        long firstSlot=availabilityId(firstDate,"13:30:00");
        postForm("/doctor/availability",cookie,"csrfToken="+enc(token)+"&action=update&slotId="+firstSlot+"&date="+firstDate+"&start=14%3A00&end=14%3A30");
        try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT start_time FROM doctor_availability WHERE id=? AND doctor_id=?")){p.setLong(1,firstSlot);p.setLong(2,doctorId);try(ResultSet r=p.executeQuery()){assertTrue(r.next());assertEquals(LocalTime.of(14,0),r.getObject(1,LocalTime.class));}}
        postForm("/doctor/availability",cookie,"csrfToken="+enc(token)+"&action=delete&slotId="+firstSlot);assertEquals(0,availabilityCount(firstSlot));
        LocalDate bookedDate=LocalDate.now().plusDays(25);postForm("/doctor/availability",cookie,"csrfToken="+enc(token)+"&action=add&date="+bookedDate+"&start=15%3A00&end=15%3A30");long bookedSlot=availabilityId(bookedDate,"15:00:00");
        long appointment;try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO appointments(patient_id,doctor_id,appointment_date,start_time,consultation_type,fee,status,payment_status) VALUES(?,?,?,'15:00:00','Video',500,'CONFIRMED','SUCCESS')",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,patientId);p.setLong(2,doctorId);p.setObject(3,bookedDate);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){assertTrue(r.next());appointment=r.getLong(1);}}
        postForm("/doctor/availability",cookie,"csrfToken="+enc(token)+"&action=delete&slotId="+bookedSlot);assertEquals(1,availabilityCount(bookedSlot));
        try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE appointments SET status='CANCELLED' WHERE id=?")){p.setLong(1,appointment);p.executeUpdate();}
        postForm("/doctor/availability",cookie,"csrfToken="+enc(token)+"&action=delete&slotId="+bookedSlot);assertEquals(0,availabilityCount(bookedSlot));
    }
    private static long availabilityId(LocalDate date,String time)throws Exception{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT id FROM doctor_availability WHERE doctor_id=? AND available_date=? AND start_time=?")){p.setLong(1,doctorId);p.setObject(2,date);p.setObject(3,LocalTime.parse(time));try(ResultSet r=p.executeQuery()){assertTrue(r.next());return r.getLong(1);}}}
    private static int availabilityCount(long id)throws Exception{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM doctor_availability WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){assertTrue(r.next());return r.getInt(1);}}}
    private static String csrfFrom(String path,String cookie)throws Exception{HttpURLConnection page=open(path,cookie);assertEquals(200,page.getResponseCode());String body=new String(page.getInputStream().readAllBytes(),StandardCharsets.UTF_8);Matcher matcher=Pattern.compile("name=\"csrfToken\" value=\"([^\"]+)\"").matcher(body);assertTrue(matcher.find());page.disconnect();return matcher.group(1);}
    private static void postForm(String path,String cookie,String data)throws Exception{HttpURLConnection post=open(path,cookie);post.setRequestMethod("POST");post.setDoOutput(true);post.setRequestProperty("Content-Type","application/x-www-form-urlencoded;charset=UTF-8");post.getOutputStream().write(data.getBytes(StandardCharsets.UTF_8));assertEquals(302,post.getResponseCode(),path+" should redirect after save");post.disconnect();}
    private static String login(String email)throws Exception{String role=email.equals(DOCTOR)||email.equals(LEGACY_DOCTOR)?"doctor":email.equals(PHARMACY)?"pharmacist":email.equals(DELIVERY)?"delivery":email.equals(ADMIN)?"admin":"patient";return loginAs(email,PASSWORD,role);}
    private static String loginAs(String email,String password,String role)throws Exception{String loginPath="/login/"+role;HttpURLConnection page=open(loginPath,null);assertEquals(200,page.getResponseCode());String body=new String(page.getInputStream().readAllBytes(),StandardCharsets.UTF_8);Matcher matcher=Pattern.compile("name=\"csrfToken\" value=\"([^\"]+)\"").matcher(body);assertTrue(matcher.find(),"role login page should have a CSRF token");assertFalse(matcher.group(1).contains("$"),"CSRF token must be rendered, not left as an EL expression");String cookie=page.getHeaderField("Set-Cookie").split(";",2)[0];page.disconnect();String data="csrfToken="+enc(matcher.group(1))+"&email="+enc(email)+"&password="+enc(password);HttpURLConnection post=open(loginPath,cookie);post.setRequestMethod("POST");post.setDoOutput(true);post.setInstanceFollowRedirects(false);post.setRequestProperty("Content-Type","application/x-www-form-urlencoded;charset=UTF-8");post.getOutputStream().write(data.getBytes(StandardCharsets.UTF_8));int status=post.getResponseCode();String response=status>=400&&post.getErrorStream()!=null?new String(post.getErrorStream().readAllBytes(),StandardCharsets.UTF_8):"";assertEquals(302,status,"login should establish a session: "+response+" token="+matcher.group(1)+" cookie="+cookie);String updated=post.getHeaderField("Set-Cookie");post.disconnect();return updated==null?cookie:updated.split(";",2)[0];}
    private static HttpURLConnection open(String path,String cookie)throws Exception{HttpURLConnection c=(HttpURLConnection)URI.create("http://127.0.0.1:"+port+path).toURL().openConnection();c.setConnectTimeout(5000);c.setReadTimeout(10000);c.setInstanceFollowRedirects(false);if(cookie!=null)c.setRequestProperty("Cookie",cookie);return c;}
    private static String enc(String value){return URLEncoder.encode(value,StandardCharsets.UTF_8);}

    private static void prepareDatabase()throws Exception{
        try(Connection c=Database.getConnection();InputStream in=WebSmokeTest.class.getResourceAsStream("/db/schema.sql")){
            String schema=new String(in.readAllBytes(),StandardCharsets.UTF_8);try(Statement s=c.createStatement()){for(String sql:schema.split(";"))if(!sql.isBlank())s.execute(sql.trim());}
            String[][] roles={{"PATIENT","Patient"},{"DOCTOR","Doctor"},{"ADMIN","Admin"},{"PHARMACIST","Pharmacist"},{"DELIVERY","Delivery"}};
            for(String[] role:roles)try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM roles WHERE role_name=?")){p.setString(1,role[0]);try(ResultSet r=p.executeQuery()){if(!r.next())try(PreparedStatement add=c.prepareStatement("INSERT INTO roles(role_name,description) VALUES(?,?)")){add.setString(1,role[0]);add.setString(2,role[1]);add.executeUpdate();}}}
            patientId=ensureUser(c,PATIENT,"Patient","PATIENT");doctorId=ensureUser(c,DOCTOR,"Doctor","DOCTOR");ensureUser(c,ADMIN,"Admin","ADMIN");ensureUser(c,PHARMACY,"Pharmacist","PHARMACIST");deliveryId=ensureUser(c,DELIVERY,"Delivery","DELIVERY");
            try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM patient_profiles WHERE user_id=?")){p.setLong(1,patientId);try(ResultSet r=p.executeQuery()){if(!r.next())try(PreparedStatement add=c.prepareStatement("INSERT INTO patient_profiles(user_id) VALUES(?)")){add.setLong(1,patientId);add.executeUpdate();}}}
            try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM doctor_profiles WHERE user_id=?")){p.setLong(1,doctorId);try(ResultSet r=p.executeQuery()){if(!r.next())try(PreparedStatement add=c.prepareStatement("INSERT INTO doctor_profiles(user_id,specialization,qualification,experience_years,consultation_fee) VALUES(?,'General Medicine','MBBS',5,500)")){add.setLong(1,doctorId);add.executeUpdate();}}}
            long legacyDoctorId=ensureUser(c,LEGACY_DOCTOR,"Dr. Meera Iyer","DOCTOR");try(PreparedStatement p=c.prepareStatement("UPDATE users SET password_hash=? WHERE id=?")){p.setString(1,"Demo123!");p.setLong(2,legacyDoctorId);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM doctor_profiles WHERE user_id=?")){p.setLong(1,legacyDoctorId);try(ResultSet r=p.executeQuery()){if(!r.next())try(PreparedStatement add=c.prepareStatement("INSERT INTO doctor_profiles(user_id,specialization,qualification,experience_years,consultation_fee,demo_profile_key) VALUES(?,'Cardiology','MBBS, MD',12,800,'demo-seed-meera-iyer')")){add.setLong(1,legacyDoctorId);add.executeUpdate();}}}try(PreparedStatement p=c.prepareStatement("UPDATE doctor_profiles SET demo_profile_key='demo-seed-meera-iyer' WHERE user_id=? AND demo_profile_key IS NULL")){p.setLong(1,legacyDoctorId);p.executeUpdate();}
            if(count(c,"categories")==0){try(Statement s=c.createStatement()){s.executeUpdate("INSERT INTO categories(name) VALUES('Wellness')");s.executeUpdate("INSERT INTO manufacturers(name) VALUES('Test Manufacturer')");}}
            if(count(c,"medicines")==0)try(PreparedStatement p=c.prepareStatement("INSERT INTO medicines(category_id,manufacturer_id,name,description,price,stock_quantity) VALUES(1,1,'Test Vitamin','Demo catalogue item',20,10)",Statement.RETURN_GENERATED_KEYS)){p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();medicineId=r.getLong(1);}}
            try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id FROM medicines ORDER BY id LIMIT 1")){r.next();medicineId=r.getLong(1);}
            try(PreparedStatement p=c.prepareStatement("SELECT id FROM appointments WHERE patient_id=? AND doctor_id=? AND status='CONFIRMED'")){p.setLong(1,patientId);p.setLong(2,doctorId);try(ResultSet r=p.executeQuery()){if(r.next())appointmentId=r.getLong(1);}}
            if(appointmentId==0){try(PreparedStatement p=c.prepareStatement("INSERT INTO appointments(patient_id,doctor_id,appointment_date,start_time,consultation_type,fee,status,payment_status) VALUES(?,?,?,'10:00:00','Video',500,'CONFIRMED','SUCCESS')",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,patientId);p.setLong(2,doctorId);p.setObject(3,LocalDate.now().plusDays(3));p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();appointmentId=r.getLong(1);}}try(PreparedStatement p=c.prepareStatement("INSERT INTO conversations(appointment_id,patient_id,doctor_id) VALUES(?,?,?)")){p.setLong(1,appointmentId);p.setLong(2,patientId);p.setLong(3,doctorId);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT INTO consultations(appointment_id,status) VALUES(?,'SCHEDULED')")){p.setLong(1,appointmentId);p.executeUpdate();}}
            try(PreparedStatement p=c.prepareStatement("INSERT INTO appointments(patient_id,doctor_id,appointment_date,start_time,consultation_type,fee,status,payment_status) VALUES(?,?,?,'12:30:00','In person',500,'COMPLETED','SUCCESS')",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,patientId);p.setLong(2,doctorId);p.setObject(3,LocalDate.now().plusDays(2));p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();long reviewAppointment=r.getLong(1);try(PreparedStatement rx=c.prepareStatement("INSERT INTO prescriptions(appointment_id,patient_id,doctor_id,clinical_notes,status) VALUES(?,?,?,'Smoke test prescription','ISSUED')",Statement.RETURN_GENERATED_KEYS)){rx.setLong(1,reviewAppointment);rx.setLong(2,patientId);rx.setLong(3,doctorId);rx.executeUpdate();try(ResultSet keys=rx.getGeneratedKeys()){keys.next();reviewPrescriptionId=keys.getLong(1);}}}}
            try(PreparedStatement p=c.prepareStatement("SELECT id FROM appointments WHERE patient_id=? AND doctor_id=? AND status='PENDING' AND payment_status='PENDING'")){p.setLong(1,patientId);p.setLong(2,doctorId);try(ResultSet r=p.executeQuery()){if(r.next())pendingAppointmentId=r.getLong(1);}}
            if(pendingAppointmentId==0)try(PreparedStatement p=c.prepareStatement("INSERT INTO appointments(patient_id,doctor_id,appointment_date,start_time,consultation_type,fee,status,payment_status) VALUES(?,?,?,'15:00:00','Secure chat',500,'PENDING','PENDING')",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,patientId);p.setLong(2,doctorId);p.setObject(3,LocalDate.now().plusDays(21));p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();pendingAppointmentId=r.getLong(1);}}
        }
    }
    private static long ensureUser(Connection c,String email,String name,String role)throws Exception{try(PreparedStatement p=c.prepareStatement("SELECT id FROM users WHERE email=?")){p.setString(1,email);try(ResultSet r=p.executeQuery()){if(r.next())return r.getLong(1);}}try(PreparedStatement p=c.prepareStatement("INSERT INTO users(full_name,email,password_hash,role) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setString(2,email);p.setString(3,PasswordUtil.hash(PASSWORD));p.setString(4,role);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();return r.getLong(1);}}}
    private static int count(Connection c,String table)throws SQLException{try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM "+table)){r.next();return r.getInt(1);}}
}
